import 'package:flutter/material.dart';
import '../../services/api.dart';

class FixedClientsScreen extends StatefulWidget { const FixedClientsScreen({super.key, required this.api}); final ApiClient api; @override State<FixedClientsScreen> createState() => _FixedClientsScreenState(); }
class _FixedClientsScreenState extends State<FixedClientsScreen> { List<dynamic> contracts=[]; bool loading=true; String? error; @override void initState(){super.initState();_load();} Future<void> _load() async {setState(()=>loading=true);try{contracts=await widget.api.get('/fixed-clients') as List;error=null;}catch(e){error='$e';}if(mounted)setState(()=>loading=false);} Future<void> _pay(String id) async {await widget.api.patch('/fixed-clients/payments/$id',{});await _load();}
  @override Widget build(BuildContext context){if(loading)return const Center(child:CircularProgressIndicator());return RefreshIndicator(onRefresh:_load,child:ListView(padding:const EdgeInsets.all(16),children:[Text('Clientes fixos',style:Theme.of(context).textTheme.headlineSmall),if(error!=null)Text(error!),...contracts.map((contract){final payments=(contract['payments'] as List? ?? []);final paid=payments.where((p)=>(p['status']??'')=='concluido').length;return Card(child:ExpansionTile(title:Text('${contract['clientName']} · ${contract['code']}'),subtitle:Text('${contract['barberName']} · $paid/${payments.length} parcelas pagas'),children:[for(final payment in payments)ListTile(title:Text('${payment['date']} · R\$ ${((payment['services']?['price'] as num?)??0).toStringAsFixed(2)}'),trailing:payment['status']=='concluido'?const Icon(Icons.check,color:Colors.green):FilledButton(onPressed:()=>_pay('${payment['id']}'),child:const Text('Receber')))]));})]));}}
